real g(real x)
{
	return sin(x) + cos(x);
}

draw(graph(g,-3*pi,3*pi,n=700,join=operator ..),red);
trig_axes(-3*pi,3*pi,-2,2,pi/2,1);
layer();
rm_trig_labels(-5, 5, 2);
[/asy]

Let $O$ be center of the first sphere, and let $P$ be the center of the second sphere.  Then
\[OP = \sqrt{(-2 - 12)^2 + (-10 - 8)^2 + (5 - (-16))^2} = 31.\][asy]
unitsize(1 cm);

pair A, B, O, P;

O = (0,0);
P = 8*dir(15);
A = dir(195);
B = P + 2*dir(15);

draw(Circle(O,1));
